INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1160290-stat211', 'stk-user6966', 'STAT 211', 'info', '{"desc": "ما حولك أحد للأسف كما هو متوقع من طلاب الإدارة >_<\" خلصت الكورس ومحد رد .\n\nالكورس يتحدث عن الإحصاء في مجال البزنس . ومن إسمه , Stat for business. والكتاب المُستخدم فيه سيء ومُمل رغم كثرة التمارين فيه . وتطبيقات هذا الكورس عديدة ومفيدة.\n\nالمواضيع التي يغطيها المُقرر :\n(شابتر 1)\nبتدرس فيه أولاً ماهو علم الإحصاء وإستخداماته\n(شابتر 2)\nثم إلى أنواع البيانات\n(شابتر 3)\nثم إلى أحد الشباتر المهمة في الكورس وهو كيفية تمثيل البيانات بإستخدام الcharts و graphs وهذا أحد الشباتر الي الشباب يخبصو فيه , فنصيحة لا تغيب في هذا الشابتر] .\n\n(شابتر 4 )\nتتطرق إلى جزء جديد ومهم وهو الـ الإحتماليات (Basic Probability) يتحدث عن فضاء العينة وعناصر المجموعة وبعض القوانين في الإحتماليات . شابتر مهم لا تغيب فيه]\n\n(شابتر5 )\nتنتقل بعدها إلى توزيعات الإحتماليات (الـ discrete) وتتطرق لأنواع جديدة من المسائل بتدرس فيها التوزيعات التالية:\nPoisson Dist.\nBinomial Dist.\nHypergeometric Dist.\n\nالشباب الي يدرسون stat319 يتطرقون لتوزيعات أكثر مثل الـ Gamma وغيرها .\nوهذا الشابتر يعتمد على الذي قبله , وبتجيك مسائل أحياناً ما تعرف رجلك من راسك , فلا تغيب !\n\n(شابتر 6)\nفي هذا الشابتر تتطرق لتوزيعات جديدة خاصة في اللـ (Continuous) وأهمها هو الـ Normal Dist.\nوأيضاً :\nExponential Dist. (لحساب الوقت , وهو له علاقة بالـ بوسّون , poisson Dist. )\nUniform Dist. (سهل وبسيط )\n\nفي هذا الشابتر راح تتطرق لمشكلة جديدة وهي الـ Standarization ,\n\nمثال :\nأحمد جاب 30/50 في مادة ماث001 وأفرج سكشنه هو 31/50 , وعبدالعزيز حصل على 72/100 في نفس المادة ماث001 وأفرج سكشنه هو 69/100 . من أفضل أحمد أو عبدالعزيز ؟ في هذه المسألة المقياس مُختلف , لذلك الـ Standardization بإستخدام الـ Normal table بيعلمك كيف تحسبها.\n\n(شابتر 7)\nبتنتقل لدرس جديد بعيد عن توزيعات الإحتماليات, وهو العيّنات (Sampling) . كيف تقدر تأخذ عيّنة من السكان ؟ في هذا الشابتر بتتعلم عدة طرق لأخذ العينات , وكذلك الأخطاء في العيّنات (errors)\nوأيضاً كيفية معرفة الـ mean والـ STD للعيّنة وهذا مهم جداً للشابترين القادمات . وكذلك Central Limit Theorem\n\n(شابتر 8 )\nبتتكلم بشكل مكثف هنا عن الـ Confidence Interval . وهي نسبة الثقة عند أخذ العينات .\nبتتعلم أن مافيه شي اسمه 100% واثق , فيه 99 ونازل …\nفي الطب مثلاً يطمحون إلى الـ99% في العمليات الجراحية .\nفي البزنس مثلاً, يطمحون إلى 90% من الثقة (تتسائل عن العشرة بالمية ؟ هم متعمدين كذا عشان يكون في risk )\n\n(شابتر 9 )\nلا يوجد\n\n(شابتر 10)\nتكملة للشابتر السابق , اللهم أنك في هذا الشابتر راح تطبق تقنيات تساعدك على المقارنة بين عيّنتين مختلفات من سكّانين مختلفان .\n\n…\n\nبشكل عام ,\nالمياجر أسئلتها straight Forward وسهلة نسبياً , فيه أسألة بالمياجر اكتب القانون وطبّق .\nأيضاً يوفرون لك القوانين (قد تختلف هذه السياسة من ترم إلى ترم). لكن طبعاً لابد من اسئلة اللف والدوران لكن جداً بسيطة ولا تقارن بتركات ماث 001 و 002 وغيرها.\n\nالصعوبة تكمن في شباتر الـ probability كونها جديدة على الطلاب مخهم ما نضج للتعامل معها (فعشان كذا لا تغيب !).\n\nفيه طلاب ياخذون F وفيه طلاب يياخذون A+ .\nوالقاسم المشترك عند الي ياخذون F هو عدم الحضور , وعدم الكتابة في الكلاس بالنوت مع الأستاذ والإكتفاء بالإنصات فقط .\n\nالتحميل :\nاضغط هنا لتحميل نوتات الأستاذ محمد صالح من غير حلول.\n\nملاحظات :\n*discrete = يأخذ أرقام integers , مثل 0 , 1 , 2 , 3 …الخ\n*Continuous = ببساطة , جميع الأرقام , ويتم حله بالتكامل.\n*dist. = distribution\n*استعملت المصطلح سكّان للـ population\n*بالنسبة لنوتات الأستاذ محمد صالح : الأستاذ يعمل update لنوتاته , ويقوم بإضافة أمثلة ويحذف *أمثلة , فقد تختلف الأسئلة من ترم إلى ترم . ولا أنصحك بشراء النوتات محلولة من المكتبة لأنها قديمة .\n*قد تكون هناك أخطاء في ما ذكرت لأني تحدثت باستعمال فهمي للكورس فالمعذرة\n\nدعواتكم لأمي وأبي ولي في ظهر الغيب 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stat-211-statistics-for-business-i/120633/5", "user": "user6966", "ts": 1357704829000, "tid": 120633, "pn": 5}}', 1357704829000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437690-stat211', 'stk-practice', 'STAT 211', 'info', '{"desc": "المادة بسيطة تتكلم عن اساسيات الاحصاء : probability - variance - sample - distributions - statistical graphs … etc\n\nسهلة لكن انتبه تضيع المياجر واللاب لانها مضمونة … الفاينل ما يمزح\n\nمشكلة المادة ذي ما يدرسوها الا دكاترة جدا سيئين : الصاوي ومصور والصباح\n\nموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stat-211-statistics-for-business-i/120633/9", "user": "Practice", "ts": 1451686451000, "tid": 120633, "pn": 9}}', 1451686451000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1509679-stat211', 'stk-_182', 'STAT 211', 'info', '{"desc": "الله يعطيك العافية، أتوقع كلام الأخ ينفع مرجع لأي طالب بياخذ المادة، أزيد على كلامه بس أنّ نوتة الأستاذ محمد صالح كافية كمصدر مذاكرة وتغنيك تمامًا عن الكتاب\n\nالمادة بسيطة، مفيدة ومهمة جدًُّا لجميع طلاب كلية الأعمال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stat-211-statistics-for-business-i/120633/10", "user": "_182", "ts": 1557766414000, "tid": 120633, "pn": 10}}', 1557766414000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p77297-stat211', 'stk-user874', 'STAT 211', 'info', '{"desc": "السلام عليكم\n\nشباب انا ماادري اش مسويين قسم الادارة بهالمادة http://skfupm.com/vb/images/smilies/confused.gif\n\nماأدري على اي اساس تم توزيع الدرجات بهالشكل :\n\n* الكلاس وورك 10 %\n*اللاب وورك 10%\n* فيرست ميجر 20%\n*سكند ميجر 20%\n* الفاينال (( 40 % ))\n\n^\n^\n^\n^\nلاحظو الفاينال كم لكن ابلعوها وناظروا تحت اش سوو بالتوزيع بعد مااخذنا السكند ميجر\n\n* الكلاس وورك 10 %\n*اللاب وورك 10%\n* فيرست ميجر 15%\n*سكند ميجر 20%\n* الفاينال (((((((( 45 % )))))))\n\nوفوق هذا ماخلصنا شرح المادة الا في آخر يوم يوم الاربعاء وعطونا كويز ولا سوينا مراجعة للمادة ابد وكان اليوم اللي بعده فاينال اسلامي واعلنو المادة ستاندارد\nوالفاينال comprehensive وجت الاسئلة بنمط جديد ماعهدناه ابد ومعقدة\nوالفاينال كان وقته جدا غير مناسب كان ضغط رهيب مع مواد الICS والACCT كانت فتراتهم جدا متقاربه\n\nوللأسف النتيجة ماوضعت في الويب ستي ولا حتى في موقع الاستاذ وضعت بصمت على باب غرفته ولا علمت الا والدرجة في Transcript\nوعشرة من الطلاب ماخذين F عنده\n\nسؤال بسيط:\nفي وجود مادة سهله وبسيطة وممتعة في نفس الوقت هل يعني من المفترض جعلها مادة ألغاز وفك رموز ومصطلحات لأول مره اسمعها في ورقة الامتحان وسخرية الدكتور (ماودي اقول اسمه) بالطلاب في وقت امتحان الفاينال وهو ماسك المكرفون ويستهزئ: ((الطلاب اغبياء اليوم )) ويقهقه بينما اوراق الطلاب غرقت من عرقهم\n\nأشبه ما يكون بتصفية حساب!! |5|", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stat211/48096/1", "user": "user874", "ts": 1118746448000, "tid": 48096, "pn": 1}}', 1118746448000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p77346-stat211', 'stk-user607', 'STAT 211', 'info', '{"desc": "تعديل في المعلومات\n\nالميجر الأول علية 20 %\nوالثاني 15 %\nوالفاينل 45 %\nطبعا هذا في صالح الطلاب لأن الكثير خبض في ميجر 2\n\nوالمشكلة في الكوردنيتر حق المالدة STAT 211\nهو إلي مسوي شديد ما أدري ليش مع ان المادة ما تستاهل\n30 طالب أخذو F في هذة المادة على كلام أحد المدرسين\n\nوالطالب إلي يجيب على الأفرج يا خذ +D ليش\n\nما أدري الحمد للة خلصنا من الأولى باقي الثانية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stat211/48096/7", "user": "user607", "ts": 1118836878000, "tid": 48096, "pn": 7}}', 1118836878000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1423177-stat211', 'stk-almax', 'STAT 211', 'info', '{"desc": "بالنسبة لي stat 211-212 سهل مو صعب بسسسسس الطلاب عاطين المادة اكبر من حجمهما و انا شخصيا شفتها في طلاب الادارة بشكل عام اي مادة فيها شوي ماث يصعبوها ويعطوها اكبر من حجمها\n\nالمادة فيها بعض الشباتر الصعبه بس الباقي سهل و ينفهم.\n\nمثل ما قلت من قبل درجة الصعوبة و التقيم يختلف من شخص الى شخص\n\nبالتوفييق ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/169125/12", "user": "almax", "ts": 1438341300000, "tid": 169125, "pn": 12}}', 1438341300000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p751251-stat211', 'stk-m7md3804', 'STAT 211', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nمرحبا شباب\n\nمحمد صالح ينصح ويشدد على مراجعة الهومورك وكذا مره يقول الميجر كله من الهوموورك 🚬\n\nاللي عنده هوموورك تشابتر 5 & 6 & 7 يعطيني خبر تكفوووووووون عآجل 😭\n\nصار لي اسبوعين اركض ورى الدكتور اقوله وين السلوشن يقول بالويب ستي :sneezing_face:\n\nوللجميع دعوة من القلب عن ظهر غيب ع َ السلخ اللي يبي يصير يوم الثلاثاء 😭\n\nبالتوفيق جميعآ ،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/5-6-7-211/99803/1", "user": "m7md3804", "ts": 1293227235000, "tid": 99803, "pn": 1}}', 1293227235000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5877-stat211', 'stk-user5877', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\n\nالتحضير :دايما واحلم ينسى هههه\nطريقة الشرح :على البروجكتر على نوتاته\nالكويزات :سهله مايله الى الصعوبه قليلا\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:a++\nالصوت:واضح جدا\nإضافات :مدرس شريح في stat 211 ما ينتفوت بس عصبي اشوي يعصب اذا سئل سؤال وما حد جاوب عليه متشدد قليلا بس تستفيد انصح فيه وبقوة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p769710-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/14", "user": "user5877", "ts": 1295719071000, "tid": 68398, "pn": 14}}]}', 1295719071000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-waleedx11-stat211', 'stk-waleedx11', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT211 TERM162\n\nالتحضير:\nنهاية الكلاس.\n\nطريقة الشرح:\nالدكتور شرحه ممتاز يشرح من نوتة ممتازة سواها للكورس كامل كان يشرح منها وبعد كل فكرة فيها أمثلة تتدرج من السهولة للصعوبة.\n\nالكويزات:\nأربع كويزات متوسطة ، اذا مذاكر بتحلها بالراحة.\n\nالمياجر:\nكانت ميدتيرم عليه 30% الترم ذا مش مياجر ، وكان عبارة عن 7 أسئلة ريتن .\n\nالفاينلات:\nكومبريهنسف عليها 40% من الكورس ، كانت 9 أسئلة ريتن تقريباً و 10 ملتبل تشويس بسيطة في النهاية.\n\nالقريد النهائي:\nأعطي الدكتور A لشرحه الممتاز وقدرته على إيصال المعلومة.\n\nالصوت:\nصوته واضح ومفهوم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473905-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/39", "user": "waleedx11", "ts": 1495886656000, "tid": 68398, "pn": 39}}]}', 1495886656000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10407-stat211', 'stk-user10407', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "171-STAT211\nالتحضير : يوميا بداية كل كلاس بالسيريال نمبر\nطريقة الشرح : من نوتته الخاصة ، احضر كل كلاس و بتفهم الماتيريال صح\nالكويزات : سهلة و ما تحتاج الا مذاكرة بسيطة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات :أفضل دكتور مر علي بالجامعة ، شرح ممتاز و طيب و كلاسه ما ينمل منه ابدا ، تصحيحه جيد يعطيك حقك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485605-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/41", "user": "user10407", "ts": 1515265838000, "tid": 68398, "pn": 41}}]}', 1515265838000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9840-stat211', 'stk-user9840', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172-STAT211\nالتحضير : يوميا نهاية كل كلاس بالسيريال نمبر\nطريقة الشرح : يستخدم نوتته الخاصة اللي اقل مايقال عليها انها اسطورية ,معه راح تفهم باذن الله الستات صح , شرحه جدااااااا ممتاز .\nالكويزات : ذاكر النوتة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات :\nشريح\nاخلاق\nيعطيك حقك وزيادة\nاحيانا يعصب ويعفس الكلاس كله\nاكتب معه في الكلاس وامورك تمام .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492585-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/43", "user": "user9840", "ts": 1526556909000, "tid": 68398, "pn": 43}}]}', 1526556909000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-makkahboy-stat211', 'stk-makkahboy', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT211 - 172\n\nالتحضير: يحضر بنهاية الكلاس عالبلاكبورد بالسيريال نمبر\n\nطريقة الشرح: عنده نوتاته الخاصة وملخصة وكوويييييسة مرررة. فيها تمارين غير محلولة بعد كل درسز هو يحلها في الكلاس لذلك يحتاج تكتتتب معاه أو تصور لأنها مرة مفيدة في المذاكرة وتغنيك عن الكتاب.\n\nالكويزات: متوسطة (ذاكر نوتاته والمساءل المحلولة) بتجيب درجات عالية.\n\nالمياجر: كومن\n\nالفاينل: كومن\n\nالصوت : وااااضح\n\nإضافات:\n- الدكتور ماشاء الله عليه صاحب دم حااار جدا ويععصصصصب 😠 إذا تأخرت ومايدخل بعض الأحيان (الوقت عنده مقدس)\n- في أول الكلاس يلخص ما تم أخذه في آخر كلاس ويسأل اسئلة عامة لو محد جاوب كذا مرة بيعصصصصصب على الكلاس ويهدد يقول we will\nhave quiz every class\nوطبعا ماقد سواها الله يجزاه خير 👏\n- من ناحية شرح فهو شرييييح ماشاء الله تبارك الرحمن\n- الهوموركات : هومورك كتابة written ومتتتعبة صراحة يطلب كل أسبوع هومورك فلا تأخر أي شيء.\n- تصحيحه يعطيك حقك ومايظلمك\n- كلاسه ممتع صراحة لأنه كلاس تحسه نشيط ومافي أحد يقدر يغفل 😏…\n\nالقريد النهائي: A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493674-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/44", "user": "makkahboy", "ts": 1528083149000, "tid": 68398, "pn": 44}}]}', 1528083149000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hyt-stat211', 'stk-hyt', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Stat 211- 181\nStat 212-182\n\nالتحضير: يحضر بداية الكلاس عالبلاكبورد بالسيريال نمبر وشديد في التحضير اول الاسابيع . وانتبه لو على الحضور درجات لانه ينقص. 211 ما كان على الحضور درجات, 212 كان عليه 5%\n\nطريقة الشرح: عنده نوتاته الخاصة وملخصة وكوويييييسة مرررة. فيها تمارين غير محلولة بعد كل درس هو يحلها في الكلاس لذلك يحتاج تكتتتب معاه لا تصور.\n\nالكويزات: متوسطة (ذاكر نوتاته والمساءل المحلولة) بتجيب درجات عالية.\n\nالمياجر: كومن ( بس هو اللي كان يحط الاسئلة )\n\nالفاينل: نفس المياجر\n\nالصوت : واضح\n\nإضافات:\n- الدكتور ماشاء الله عليه طيب وباله طوييييل في كل شي ومتساعد. في الكورسين كان عنده بونس ورفع تقريبا بعض الطلاب اللي بدعوا في الفاينل قريد كامل.\n- في أول الكلاس يلخص ما تم أخذه في آخر كلاس ويسأل اسئلة عامة.\n- الهوموركات : هومورك كتابة وغالبا تكون طويلة وتقريبا كل اسبوع تسليم.\n- تصحيحه يعطيك حقك وبعض الاحيان يزودك لو راجعته.\n- اخر شي لو في واحد غثيث في الكلاس ممكن تكره حياتك مع الدكتور , لانه لو فصل عليه بيفصل على الكلاس كامل\n\nالقريد النهائي: A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507239-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/45", "user": "hyt", "ts": 1552564094000, "tid": 68398, "pn": 45}}]}', 1552564094000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-stat211', 'stk-_182', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT211-182\n\nالتحضير: نهاية المحاضرة بالرقم التسلسلي، شديد في التحضير أول الأسابيع -دقيقة وحدة تفرق-، ومع قرب انتهاء الترم ما يصير يعلق على المتأخرين، يقبل تحضر مع شعبة ثانية\nطريقة الشرح: عنده نوتة يشرح منها، يفتحها بالوورد ويستخدم السبورة\nالكويزات: المفروض نختبر 5 كويزات، اختبرنا 3 والإثنين الباقين قال أنه عطى الكل فل، الكويزات فكرتها مثل أسئلة النوتة\nالمياجر: موحّدة، ذاكر النوتة حقته وأمورك طيبة إن شاء الله\nالفاينلات: زي المياجر\nالقريد النهائي: +A\nالصوت: واضح\nإضافات:\n\n- أول محاضرة يمكن يعطيكم انطباع أنه شديد مرة، مثلًا يمكن تسمعون: “هذي مواعيد الكويزات ومرح أذكركم مرة ثانية”، والواقع أنه يذكّر قبل كل كويز، بل ويؤجل الكويز إذا الطلاب بغوا\n- يعمل مراجعة قبل كل ميجر يلخص فيها اللي بيجيكم فيه، أكرر: النوتة حقته أكثر من كافية، لا تضيّع وقت بقراءة الكتاب إذا كنت بتقراه فقط عشان الاختبار\n- النوتة عبارة عن مفاهيم تليها أمثلة، والأمثلة غير محلولة، هو يحلها معكم وقت المحاضرة\n- يتكلم عربي إذا لزم الأمر، وما يمانع الطلاب يسألون بالعربي إذا ما فهموا\n- متجاوب بالإيميل، ومتواجد في الساعات المكتبية\n- نهاية الترم قال إذا الجميع عمل تقييم الأستاذ بعطيكم درجة كاملة في كويزّين، قال لنا بعدها في المحاضرة خلاص كلكم عطيتكم الدرجة، لاحقًا أحد الطلاب قال لنا أنه سأله وقال لا ما عطيتكم، فما أدري عنه.\n- ما عنده بونص\n\nالدكتور ممتاز، شرحه واضح، النوتة مرتّبة، طيّب ويفهمك صح.\n\nأنصح فيه كخيار أول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509678-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/46", "user": "_182", "ts": 1557766102000, "tid": 68398, "pn": 46}}]}', 1557766102000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawafmkz-stat211', 'stk-nawafmkz', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68398", "n": "Dr. Mohammed Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "stat211 - 192\n\nالتحضير : في أول دقيقة، يكره التأخير ويحاسب عليه.\nطريقة الشرح : يفتح نوتته الخاصة “غير محلولة” ويشرح المفهوم وليه نستخدمه ووش فايدته ويحل الأسئلة ويكتب كل شي على السبورة، لازم تكتب معه لأن يرفع النوتة غير محلولة ويمسح السبورة كثير. شرح ممتاز جدا (ما شاء الله عليه) وأحيانا سريع فلازم تركز يحب الطلاب يشاركون معه ويتفاعلون.\n\nفي فترة كورونا صار يرفع النوتة محلولة للطلاب ويشرح عليها بنفس الطريقة العادية مع تساهل في التحضير\n\nالكويزات : قبل كورونا كوزين شبيهة للنوتة\nالمياجر: الميجر الأول ريتن، متوسط الصعوبة نفس أفكار الواجب وبعض الأسئلة منه.\nالفاينلات : لا يوجد. في فترة كورونا صار فيه 5 اختبارات شبه قصيرة لكل شابتر اختبار مستواها سهل لمتوسط شبيهة بالنوتة وأسئلة الدكتور الإضافية.\nالقريد النهائي: A+++\nالصوت: واضح\nإضافات : الدكتور محترم وأخلاق وحريص على فايدة الطلاب أنصح به وبشدة.\n\nنوتة الدكتور لترم 192 مرفوعة في الريسورسز محلولة كافة الشباتر + الأسئلة الإضافية ]", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525354-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-saleh/68398/47", "user": "NawafMKZ", "ts": 1599250829000, "tid": 68398, "pn": 47}}]}', 1599250829000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hard-worker-stat211', 'stk-hard-worker', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68419", "n": "Dr. E. Al-Sawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT211 …Term 151\nSTAT212 … Term 153\nالأخلاق : الدكتور أخلاقه جدا عالية ومتعاون مع الطلاب لأبعد درجة و يحب يمزح وينكت مع الطلاب\nالشرح : الدكتور شرحه واضح لكن جدا سريع ويبغاله الواحد يجي مروق ع الاخر عشان يلحق معاه , يكتب بالسبورة ويمسح ويركز كثير على كيف جت الفورمولا وكيف اشتقيناها ( أنا صراحه اذا جاء يشرح كيف جاء القانون أضيع واقول أحفظ القانون ياعمي مو لازم أفهمه لان في النهاية اللي بتحتاجه القانون النهائي وطريقة تطبيقه )\nالمياجر: كومون (كانت 3 مياجر, أنا أنصح الواحد انه يركز على المياجر ومايضيعها وصراحة اللي يذاكر لها كويس يقدر يجيب درجة باذن الله ونصيحتي ان الواحد يضمن درجة في المياجر لان الفاينل جدا جدا طويل وصعب )\nقريدي للدكتور: B+\nاضافات أنا عرفت نظام المادة من قبل انها تحتاج جهد بالمياجر لأنها مضمونه والفاينل عاد اللي يكتبه ربك والحمدلله جبت درجات مرضية\nB , A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1461880-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/e-al-sawi/68419/35", "user": "HARD-WORKER", "ts": 1478467531000, "tid": 68419, "pn": 35}}]}', 1478467531000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-stat211', 'stk-khdsa2022', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68419", "n": "Dr. E. Al-Sawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : عصام الصاوي\nالمادة: Stat211\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يحضر كل يوم معدا بعض الايام الي مايحضر فيها و بعض الاحيان يحضر في بدايه الكلاس و بعض الاحيان في نهايته و يعصب اذا تأخر الطالب عن الحصه لكن إذا جه قبل التحضير ف انه يحضره\n\nطريقة الشرح : شرح الدكتور جدآ سيئ وصعب انك تفهم عليه لازم انك تكون محضر الدرس علشان تمشي معاه\n\nالكويزات : عطانا كويز واحد وكان نوعا ما متوسط و عطانا كويزين لكن كانوا اون لاين\n\nالمياجر: كومن،، لكن تصحيه شديد جدآ جدآ و يدقق على كل شي\n\nالفاينلات : كومن وكانت خيارات\n\nالقريد النهائي: D بسبب شرح الدكتور الي ممكن يقال عنه سيئ و تصحيحه الشديد جدا\n\nالصوت: واضح\n\nإضافات : الدكتور في خلال المحاضره يعطي اسأله مستواها A+ الي يحلها في الكلاس يعطيه بونص او ان يسأل عن سؤال ب الدرس السابق و يعطي بونص عليه،، تحتاج انك تكون محضر علشان تفهم و تحل\nو\nالدكتور يعصب جدا اذا شاف احد يمسك جوال ف حاول اذا كنت معه لاتمسك الجوال كثير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518821-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/e-al-sawi/68419/43", "user": "Khdsa2022", "ts": 1578292994000, "tid": 68419, "pn": 43}}]}', 1578292994000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_cfa-stat211', 'stk-_cfa', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا بصراحة أوضح اللي واجهته معه يعني طلعت معه ب D+ في Stat 211 وأخذت A في Stat212 وبمجهود أقل مع دكتور آخر كان يشرح بطريقة مغايرة تجعلك اقرب للمادة.وكماتعرفون الاختبارات كومون\n\nوهذا مسبب لي مشكلة في الترانكسربت اثناء التقديم على الشركات غالبا يسألوني لما هذا التباين في المادتين وبكل أريحيه أجيب السبب هو مدرس المادة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p640676-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/24", "user": "_CFA", "ts": 1277088927000, "tid": 68463, "pn": 24}}]}', 1277088927000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousefli-stat211', 'stk-yousefli', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT211-183\n\nالتحضير : متساهل في التأخير البسيط لكن ما يسمح ميك اب الا مره بالترم ، ويسمح انك تحضر مع سكشن ثاني بشرط ترم كامل او مثل ما ذكرت مره لك\nطريقة الشرح : ممتاز للامانة ويحاول يفهمك كيف تحل ويجيب لك اختصارات واشياء خارج الكتاب لكن مشكلته يعلمك كيف تحل ما يربط لك بموضوعات الادارة لان المادة ذي جدا مهمة لكل التخصصات وكيف ربطها\nاخلاقه: دكتور طيب لكن حقاني بالمرة لك حق بتاخذه والغيابات يقولك ما تفرق حضرت ٨ ولا جيت ٨ في النهاية مراح ادف واحد بسبت الغياب وخلوق\nالكويزات : يعطيها القريدر ولو فيه مشكلة كلمه ويمشيها\nالتصحيح: حقاني مثل م قلت وما يعطيك زيادة في الميجر الا بحقك يعني ما فيه دف نهائيا كل الخطوات يبيها واحيانا يعطيك سؤال مفتوح\nوتشوف حله في الاولد اقزام يقول قلي وش فهمت من الصورة تكتب مثل الاولد اقزام يقولك غلط انا شرحت هالشيء ومفروض ابي كذا وكذا\nفشوف اولد اقزامته وحاول تفهم وش يدور من كل قراف لان يدوخ هالدكتور بتتعب من تصحيحه.\nالمياجر: نااااااااااار الاول كان الافرج ٤٣ والثاني ٥٠ وزاد الطلاب كم درجة لان الافرج F>>>\nالفاينلات : بسبت المياجر كانت نار جاب متوسط لكن مو سهل وكان الافرج ٢٢ من ٣٦ تقريبا\nالقريد النهائي: C+\nالصوت: واضح\n\nما انصح فيه للمادة ذي لكن بالغالب هالمادة ما يدرسها الا الصاوي، فاحيانا يكون اهو احسن الموجودين ، محمد صالح احسن لكن مو كل ترم يمسكها فأحيانا تضطر تنزل معاه وانا لو حصل لي غيره اهو والصاوي بيكون خياري لكن مثل ما قلت لا تخليه خيارك الأول.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513261-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/65", "user": "yousefli", "ts": 1564802653000, "tid": 68463, "pn": 65}}]}', 1564802653000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-stat211', 'stk-sadguts', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68463", "n": "Dr. R. Anabosi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT211 - 202\nماكان يحضر في الاونلاين\nالدكتور شرحه بطل صراحة ويشرح تفاصيل مهمة ويعطي امثلة جامدة في الكلاس ومو مثل سمعته\nعيبه اخلاقه تحس انك مع واحد حاقد عليك ويرد باسلوب غريب ولاهو متساعد ف الاوفس اور\n+كويزاته كانت صعبة\nاوفرول الدكتور خيار كويس للستات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531524-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/r-anabosi/68463/69", "user": "SadGuts", "ts": 1630067176000, "tid": 68463, "pn": 69}}]}', 1630067176000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-conanzz-stat211', 'stk-conanzz', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m68577", "n": "Dr. Mohammad Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت عنده Stat211 في 211\n\nمحترم جدا جدا\n\nوالشرح يبذل مجهوده ويوصل الفكره لو انتبهت معاه وحليت التمارين يللي يحلها\n\nالتحضير : يحضر و مهتم في التحضير وكل تأخيرتين بدرجة غياب\n\nطريقة الشرح : على السبورة وعلى السلايدات\n\nالكويزات :سهالات يراجع الشابتر قبل ما يعطينا الكويز وبعدها يعطينا الكويز وتكون نفس الفكرة اللي هوا شرحها مع تغيير بسيط والقوانين على السبوره يكتبها\n\nالمياجر: كومن ولكن طيب في التصحيح\n\nالفاينلات :كومن\n\nالقريد النهائي: A\n\nالصوت: عالي وواضح\n\nإضاقه: يرحب فيك إذا رحت له المكتب احسن ترحيب ويشرح لك بإخلاص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1006758-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-omar/68577/20", "user": "conanzz", "ts": 1331628188000, "tid": 68577, "pn": 20}}]}', 1331628188000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ksa-wolf-stat211', 'stk-ksa-wolf', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-m94263", "n": "Dr. Muhammad Riaz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT 211 - term 161\n\nالتحضير :\nكل حصة تقريبا و ماهو شديد.\nطريقة الشرح :\nمن السلايدات و شرحة ممتاز. و يجاوب على الأسئلة دائما.\nالكويزات :\nمن سهلة لمتوسطة. و تصحيحة بطل.\nالمياجر:\nكومن. متوسطة و مو هو السبب في الصعوبة بل الأستاذ مسور مالك. و تصحيحه بطل.\nالفاينال :\nوالله جاء الفاينال صلخخخ… أعلى واحد في كلاسنا جاب 25 من 35، الآفرج كان 16 في كلاسنا بس. من جديد السبب الكوردنيتر الأستاذ مسور مالك هو اللي يحط الأسألة.\nالقريد النهائي:\nA+\nالصوت:\nواضح و الأكسنت أشوفه مفهوم.\nإضافات :\n- الدكتور تصحيحه كفو و بطل. و يدفك حتى لو الحل خطأ.\n- هو كذا مسور مالك… يجيب لكم مياجر متوسطة و يصلخكم في الفاينال عشان يرجع الآفرج فانتبه منه و ذاكر زين للفاينال و هو (Comprehensive).\n- ما يدفون في القريد. لو بقي لك 0.1 على القريد اللي بعده أو حتى النجاح ما يدفونك فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466891-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-riaz/94263/27", "user": "KSA-WOLF", "ts": 1485234318000, "tid": 94263, "pn": 27}}]}', 1485234318000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-stat211', 'stk-jafar_15', 'STAT 211', 'doc', '{"docs": [{"id": "stk-dr-f176961", "n": "Dr. Nasir Abbas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "STAT 211 -181\n\nالتحضير :\nاول خمس دقايق من المحاضرة، تحضر بعد مايخلص التحضير يعتبرك متأخر\n\nطريقة الشرح :\nشرحه لاول الفصول كان يعتمد على السلايدات ويعلق عليها ويكتب في السبورة اذا كان يحتاج، لكن بعدين في الفصول اللي بعدهم يشرح عن طريق السبورة ومايستخدم السلايدات الا نهاية الفصل كمراجعة سريعة\nشرحه بالنسبة لي ممتاز جدًا وواضح\n\nالكويزات :\nمافي\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالصوت:\nالصوت واضح جدًا ، والاكسنت عنده ممتاز جدًا\n\nإضافات:\nالدكتور بشكل عام ممتاز وانصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504250-stat211", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nasir-abbas/176961/4", "user": "Jafar_15", "ts": 1546164561000, "tid": 176961, "pn": 4}}]}', 1546164561000, 1794837148, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
